"use client";

import { useSession, signOut } from "next-auth/react";
import Link from "next/link";

export function UserMenu() {
  const { data: session, status } = useSession();

  if (status === "loading") return <div className="w-32 h-8 bg-gray-200 rounded-full animate-pulse" />;

  if (!session) {
    return (
      <div className="flex flex-col gap-2">
        <Link href="/auth/signin" className="px-4 py-2 bg-black text-white rounded-xl text-center">Inloggen</Link>
        <Link href="/auth/signup" className="px-4 py-2 bg-gray-800 text-white rounded-xl text-center">Registreren</Link>
      </div>
    );
  }

  return (
    <button
      onClick={() => signOut()}
      className="px-4 py-2 rounded-xl bg-red-500 text-white hover:bg-red-600 transition"
    >
      Uitloggen
    </button>
  );
}